import { createRequire } from "node:module";
import { existsSync } from "node:fs";
import { pathToFileURL } from "node:url";
import path from "node:path";

const root = process.cwd();
const built = path.join(root, "build", "node", "luxon.js");
let luxon;
if (existsSync(built)) {
  luxon = createRequire(import.meta.url)(built);
} else {
  luxon = await import(pathToFileURL(path.join(root, "src", "luxon.js")).href);
}
const { DateTime, Duration } = luxon;

const purchaseDate = DateTime.fromObject({ day: 1, month: 1, year: 2020 }, { zone: "UTC" });
const warranty = Duration.fromObject({ days: 14 }, { conversionAccuracy: "longterm" });
const now = DateTime.fromObject({ day: 8, month: 1, year: 2020 }, { zone: "UTC" });
const age = now.diff(purchaseDate).shiftToAll();
const warrantyLeft = warranty.minus(age).shiftToAll().toString();

if (warrantyLeft !== "P1W") {
  console.log(`WHOBROKEIT_BUG: expected warrantyLeft "P1W" but got "${warrantyLeft}"`);
  process.exitCode = 1;
} else {
  process.exitCode = 0;
}
